import React, { useEffect, useState } from "react";
import axios from "axios";
import EvidenceUploadForm from "./EvidenceUploadForm";

const TechnicianDashboard = () => {
  const [jobs, setJobs] = useState([]);
  const [materialRequests, setMaterialRequests] = useState([]);
  const [user, setUser] = useState({ name: "", id: "" });
  const [showEvidenceForm, setShowEvidenceForm] = useState({});
  const handleEvidenceSuccess = (jobId) => {
    // Optionally refresh jobs or update UI after evidence upload
    setShowEvidenceForm((prev) => ({ ...prev, [jobId]: false }));
  };

  const toggleEvidenceForm = (jobId) => {
    setShowEvidenceForm((prev) => ({ ...prev, [jobId]: !prev[jobId] }));
  };

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      const u = JSON.parse(userStr);
      setUser(u);
      const token = localStorage.getItem("token");
      const config = token ? { headers: { Authorization: `Bearer ${token}` } } : {};
      axios.get(`http://localhost:5000/api/issues/assigned/${u._id || u.id}`, config)
        .then(res => setJobs(res.data));
      axios.get(`http://localhost:5000/api/material-requests/tech/${u._id || u.id}`, config)
        .then(res => setMaterialRequests(res.data));
    }
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <h1 className="text-2xl font-bold mb-6">Technician Dashboard</h1>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <div className="bg-white rounded-xl shadow p-6">
          <h2 className="font-semibold text-lg mb-2">Assigned Jobs</h2>
          <div className="text-3xl font-bold">{jobs.length}</div>
          <ul className="mt-3 text-sm">
            {jobs.map(job => (
              <li key={job.id || job._id} className="mb-4 border-b pb-2">
                <div className="flex flex-col md:flex-row md:items-center md:justify-between">
                  <div>
                    <span className="font-semibold">{job.title}</span> <span className="text-xs text-gray-400">({job.status || 'Pending'})</span>
                  </div>
                  <button
                    className="mt-2 md:mt-0 bg-indigo-500 text-white px-3 py-1 rounded text-xs hover:bg-indigo-600"
                    onClick={() => toggleEvidenceForm(job.id || job._id)}
                  >
                    {showEvidenceForm[job.id || job._id] ? 'Cancel' : 'Upload Evidence'}
                  </button>
                </div>
                {showEvidenceForm[job.id || job._id] && (
                  <div className="mt-3">
                    <EvidenceUploadForm
                      issueId={job.id || job._id}
                      onSuccess={() => handleEvidenceSuccess(job.id || job._id)}
                    />
                  </div>
                )}
              </li>
            ))}
          </ul>
        </div>
        <div className="bg-white rounded-xl shadow p-6">
          <h2 className="font-semibold text-lg mb-2">Material Requests</h2>
          <div className="text-3xl font-bold">{materialRequests.length}</div>
          <ul className="mt-3 text-sm">
            {materialRequests.slice(0, 5).map(req => (
              <li key={req.id} className="mb-1">{req.status} - {req.requestId}</li>
            ))}
          </ul>
        </div>
      </div>
      <div className="bg-white rounded-xl shadow p-6 mb-8">
        <h2 className="font-semibold text-lg mb-2">Work History</h2>
        <ul className="text-sm">
          {jobs.slice(0, 10).map(job => (
            <li key={job.id || job._id} className="mb-1">{job.title} - {job.status || 'Pending'}</li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default TechnicianDashboard;
